using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the default discriminator property from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator" — preserve compatibility.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id format from "Product|123" to just "123".
            // Existing documents use the compound format — preserve compatibility.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // HasIndex throws at runtime in EF Core 9 Cosmos provider — removed.
        // Cosmos DB indexing is managed via the container's indexing policy (Azure Portal/Bicep).
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } = null!; }

